{
  "runId": "replay-jobs-1",
  "summary": "Complete the applyJob helper to be idempotent, record partial failures, and pass all tests.",
  "allowedFiles": [
    "src/jobs/jobs.js",
    "src/jobs/jobs.test.js"
  ],
  "operations": [
    {
      "type": "update_file",
      "path": "src/jobs/jobs.js",
      "content": "export const store = { applied: {}, pending: {} };

/**
 * Apply a job by id. The operation is idempotent – calling it again with the same id
 * has no effect and returns the cached result. Partial failures are recorded in
 * `pending` so they can be retried later.
 * @param {string} id - Job identifier.
 * @param {() => Promise<any>} work - Async function that performs the job.
 * @returns {Promise<any>} Resolved with the work result or cached result.
 */
export async function applyJob(id, work) {
  // If job is already applied, return cached result.
  if (store.applied[id]) {
    return store.applied[id];
  }

  // If a previous attempt failed and is still pending, reuse that promise.
  if (store.pending[id]) {
    try {
      const result = await store.pending[id];
      // Mark as applied on success.
      store.applied[id] = result;
      delete store.pending[id];
      return result;
    } catch (err) {
      // Keep it pending until a new attempt succeeds or is manually cleared.
      // Optionally, you could rethrow or handle differently.
      throw err;
    }
  }

  // Mark this job as pending before starting work.
  const promise = work();
  store.pending[id] = promise;

  try {
    const result = await promise;
    // Record success.
    store.applied[id] = result;
    return result;
  } catch (err) {
    // Record failure but keep the promise pending so retries can resume.
    // The promise stays in `pending` so subsequent calls will wait for it.
    // Optionally, you could delete it here if you want to drop failed attempts.
    throw err;
  }
}",
      "reason": "Replace the stub with a full implementation that handles idempotency, pending failures, and proper async resolution."
    },
    {
      "type": "update_file",
      "path": "src/jobs/jobs.test.js",
      "content": "import test from 'node:test';
import assert from 'node:assert/strict';
import { applyJob, store } from './jobs.js';

test('applies once', async () => {
  // Reset store before each test.
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);

  const result = await applyJob('j1', () => Promise.resolve(1));
  assert.strictEqual(result, 1);
});

test('duplicate apply returns cached result', async () => {
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);

  const first = await applyJob('j2', () => Promise.resolve('done'));
  const second = await applyJob('j2', () => Promise.resolve('ignored'));
  assert.strictEqual(first, 'done');
  assert.strictEqual(second, 'done');
  assert.strictEqual(first, second);
});

test('failure is recorded and can be retried', async () => {
  const testId = 'failId';
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);

  // First call fails.
  await assert.rejects(applyJob(testId, () => {
    throw new Error('boom');
  }), /boom/);

  // Ensure the failure is recorded as pending.
  assert.ok(store.pending[testId]);

  // Retry should re‑try the same failing work.
  await assert.rejects(applyJob(testId, () => {
    throw new Error('boom');
  }), /boom/);
});

test('success after failure is idempotent', async () => {
  const testId = 'recoverId';
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);

  // Simulate a failure first.
  await assert.rejects(applyJob(testId, () => {
    throw new Error('boom');
  }), /boom/);

  // Now provide a successful work.
  const result = await applyJob(testId, () => Promise.resolve('fixed'));
  assert.strictEqual(result, 'fixed');

  // Duplicate call returns the same cached result.
  const again = await applyJob(testId, () => Promise.resolve('ignored'));
  assert.strictEqual(again, 'fixed');
});

test('pending promise is reused on duplicate call', async () => {
  const testId = 'reuseId';
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);

  const workPromise = Promise.resolve('reused');
  const first = await applyJob(testId, () => workPromise);
  const second = await applyJob(testId, () => Promise.resolve('ignored'));
  assert.strictEqual(first, 'reused');
  assert.strictEqual(second, 'reused');
});

test('applies multiple distinct jobs', async () => {
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);

  const r1 = await applyJob('a', () => Promise.resolve(10));
  const r2 = await applyJob('b', () => Promise.resolve(20));
  assert.strictEqual(r1, 10);
  assert.strictEqual(r2, 20);
  assert.notStrictEqual(r1, r2);
});

test('store state reflects applied and pending correctly', async () => {
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);

  await applyJob('x', () => Promise.resolve('ok'));
  assert.strictEqual(store.applied['x'], 'ok');
  assert.strictEqual(store.pending['x'], undefined);
});

test('applyJob returns rejected error on failure', async () => {
  const testId = 'errorId';
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);

  await assert.rejects(applyJob(testId, () => {
    throw new Error('final');
  }), /final/);
});"
      ,
      "reason": "Rewrite the test suite to use async/await, properly handle promises, and verify idempotency, duplicate apply, failure recording, and retry behavior."
    }
  ]
}
